// Tooie: an explicit matrix ID on a scene's first projection names its camera. Matrix distance alone
// can pair a moving camera's world scene with the previous sky scene (same view, other projection),
// and then no projection in either pair maps, so the camera snaps for a frame.
auto sceneGroupId = [&](const GameScene &scene) {
    const GameIndices::Projection &first = scene.projections[0];
    const Workload &workload = workloadQueue.workloads[first.workloadIndex];
    const Projection &proj = workload.fbPairs[first.fbPairIndex].projections[first.projectionIndex];
    return workload.drawData.transformGroups[workload.drawData.viewProjTransformGroups[proj.transformsIndex]].matrixId;
};

// Pairs whose explicit IDs differ go last, keeping distance order within each part.
std::stable_partition(matchCandidates.begin(), matchCandidates.end(), [&](const MatchCandidate &candidate) {
    const uint32_t curId = sceneGroupId(curScenes[candidate.curIndex]);
    const uint32_t prevId = sceneGroupId(prevScenes[candidate.prevIndex]);
    const bool curExplicit = (curId != G_EX_ID_IGNORE) && (curId != G_EX_ID_AUTO);
    const bool prevExplicit = (prevId != G_EX_ID_IGNORE) && (prevId != G_EX_ID_AUTO);
    return !curExplicit || !prevExplicit || (curId == prevId);
});

const uint32_t currentGroupIndex = curWorkload.drawData.viewProjTransformGroups[curProj.transformsIndex];
const TransformGroup &currentGroup = curWorkload.drawData.transformGroups[currentGroupIndex];
if (currentGroup.matrixId == G_EX_ID_IGNORE) {
    firstCurWorkloadMap.viewProjections[curProj.transformsIndex] = GameFrameMap::ViewProjectionMap();
    continue;
}

// Reuse only the first anchor with the same effective projection policy.

const uint32_t anchorGroupIndex = firstCurWorkload.drawData.viewProjTransformGroups[mappedViewProjIndex];
const TransformGroup &anchorGroup = firstCurWorkload.drawData.transformGroups[anchorGroupIndex];
const auto compatibleProjection = [](const TransformGroup &a, const TransformGroup &b) {
    if ((a.matrixId == G_EX_ID_IGNORE) || (b.matrixId == G_EX_ID_IGNORE)) return false;
    if (a.matrixId != b.matrixId) return false;
    if (a.matrixId == G_EX_ID_AUTO) return true;
    return (a.decompose == b.decompose) &&
        (a.positionInterpolation == b.positionInterpolation) &&
        (a.rotationInterpolation == b.rotationInterpolation) &&
        (a.scaleInterpolation == b.scaleInterpolation) &&
        (a.skewInterpolation == b.skewInterpolation) &&
        (a.perspectiveInterpolation == b.perspectiveInterpolation);
};
if (compatibleProjection(currentGroup, anchorGroup)) {
    firstCurWorkloadMap.viewProjections[curProj.transformsIndex] = firstCurWorkloadMap.viewProjections[mappedViewProjIndex];
    continue;
}

// The check sets depend only on per-call properties, so build them per hash bucket from the
// distinct properties on each side instead of visiting every current x previous call pair,
// which is quadratic in the bucket size (557-call buckets, 440k pairs per frame in Hailfire
// Peaks with extended draw distance). Sorted, deduplicated vectors iterate in the same order
// as the std::set they replace, so the matching below sees identical input.
thread_local std::vector<IndexPair> transformCheckSet;
thread_local std::vector<IndexPair> tileCheckSet;
thread_local std::vector<IndexPair> lookAtCheckSet;

struct CallSide {
    uint64_t hash;
    uint32_t worldMin, worldCount, tileIndex, tileCount, lookAt;
    bool transform, tileInterpolation, tileMatching, textureGen;
};

// Only calls owned by the first workload of each scene can produce check pairs.
const uint32_t textureGenMask = G_LIGHTING | G_TEXTURE_GEN;
auto collectSides = [&](const std::multimap<uint64_t, GameCallMap> &hashMap, const GameScene &scene, uint32_t ownerWorkloadIndex, std::vector<CallSide> &sides) {
    sides.clear();
    for (const auto &it : hashMap) {
        const GameIndices::Projection &projIndices = scene.projections[it.second.sceneProjIndex];
        if (projIndices.workloadIndex != ownerWorkloadIndex) continue;
        const Workload &workload = workloadQueue.workloads[projIndices.workloadIndex];
        const Projection &proj = workload.fbPairs[projIndices.fbPairIndex].projections[projIndices.projectionIndex];
        const GameCall &call = proj.gameCalls[it.second.callIndex];
        CallSide side;
        side.hash = it.first;
        side.worldMin = call.callDesc.minWorldMatrix;
        side.worldCount = (call.callDesc.maxWorldMatrix - call.callDesc.minWorldMatrix) + 1;
        side.tileIndex = call.callDesc.tileIndex;
        side.tileCount = call.callDesc.tileCount;
        side.transform = it.second.doTransformMatching;
        side.tileInterpolation = it.second.doTileInterpolation;
        side.tileMatching = it.second.doTileMatching;
        side.textureGen = (call.callDesc.geometryMode & textureGenMask) == textureGenMask;
        side.lookAt = 0;
        if (side.textureGen) {
            // FIXME: We assume the same look at is used throughout the entire draw call, so we only check the first vertex.
            const uint32_t vertexIndex = workload.drawData.faceIndices[call.meshDesc.faceIndicesStart];
            side.lookAt = workload.drawData.lookAtIndices[vertexIndex] >> RSP_LOOKAT_INDEX_SHIFT;
        }

        sides.emplace_back(side);
    }
};

// Both lists come out in hash order (multimap order), so equal-hash buckets pair up in one merge walk.
thread_local std::vector<CallSide> curSides;
thread_local std::vector<CallSide> prevSides;
collectSides(curCallHashMap, curScene, firstCurProjIndices.workloadIndex, curSides);
collectSides(prevCallHashMap, prevScene, firstPrevProjIndices.workloadIndex, prevSides);

thread_local std::vector<IndexPair> curRanges, prevRanges;
thread_local std::vector<uint32_t> curLookAts, prevLookAts;
struct TileKey {
    uint32_t tileCount, slot;
    bool matching;
    uint64_t hash;
    uint32_t tileIndex;
    bool operator<(const TileKey &other) const {
        return std::tie(tileCount, slot, matching, hash, tileIndex) < std::tie(other.tileCount, other.slot, other.matching, other.hash, other.tileIndex);
    }
};

thread_local std::vector<TileKey> prevTiles;
auto byCountThenStart = [](const IndexPair &a, const IndexPair &b) { return (a.second < b.second) || ((a.second == b.second) && (a.first < b.first)); };
size_t c = 0, q = 0;
while ((c < curSides.size()) && (q < prevSides.size())) {
    if (curSides[c].hash < prevSides[q].hash) { c++; continue; }
    if (prevSides[q].hash < curSides[c].hash) { q++; continue; }
    const uint64_t hash = curSides[c].hash;
    const size_t cBegin = c, qBegin = q;
    while ((c < curSides.size()) && (curSides[c].hash == hash)) c++;
    while ((q < prevSides.size()) && (prevSides[q].hash == hash)) q++;

    // Transforms: distinct (first world matrix, matrix count) ranges on each side.
    curRanges.clear();
    prevRanges.clear();
    for (size_t i = cBegin; i < c; i++) if (curSides[i].transform) curRanges.emplace_back(curSides[i].worldMin, curSides[i].worldCount);
    for (size_t i = qBegin; i < q; i++) if (prevSides[i].transform) prevRanges.emplace_back(prevSides[i].worldMin, prevSides[i].worldCount);
    std::sort(curRanges.begin(), curRanges.end(), byCountThenStart);
    curRanges.erase(std::unique(curRanges.begin(), curRanges.end()), curRanges.end());
    std::sort(prevRanges.begin(), prevRanges.end(), byCountThenStart);
    prevRanges.erase(std::unique(prevRanges.begin(), prevRanges.end()), prevRanges.end());
    size_t pr = 0;
    for (const IndexPair &curRange : curRanges) {
        while ((pr < prevRanges.size()) && (prevRanges[pr].second < curRange.second)) pr++;
        for (size_t k = pr; (k < prevRanges.size()) && (prevRanges[k].second == curRange.second); k++) {
            for (uint32_t w = 0; w < curRange.second; w++) {
                const uint32_t curWorldMatrix = curRange.first + w;
                const uint32_t curGroupIndex = firstCurWorkload.drawData.worldTransformGroups[curWorldMatrix];
                const TransformGroup &curGroup = firstCurWorkload.drawData.transformGroups[curGroupIndex];
                const uint32_t prevWorldMatrix = prevRanges[k].first + w;
                const uint32_t prevGroupIndex = firstPrevWorkload.drawData.worldTransformGroups[prevWorldMatrix];
                const TransformGroup &prevGroup = firstPrevWorkload.drawData.transformGroups[prevGroupIndex];

// Tiles: the same tile slot of calls with the same tile count. When both calls match
// tiles, only tiles with the same TMEM hash pair up, so previous tiles are sorted by
// (count, slot, matching, hash) and each current tile takes one or two ranges.
prevTiles.clear();
for (size_t i = qBegin; i < q; i++) {
    const CallSide &prevSide = prevSides[i];
    if (!prevSide.tileInterpolation) continue;
    for (uint32_t t = 0; t < prevSide.tileCount; t++) {
        const uint64_t tileHash = prevSide.tileMatching ? firstPrevWorkload.drawData.callTiles[prevSide.tileIndex + t].tmemHashOrID : 0;
        prevTiles.push_back({ prevSide.tileCount, t, prevSide.tileMatching, tileHash, prevSide.tileIndex + t });
    }
}

std::sort(prevTiles.begin(), prevTiles.end());
auto bySlot = [](const TileKey &x, const TileKey &y) { return std::tie(x.tileCount, x.slot) < std::tie(y.tileCount, y.slot); };
auto byHash = [](const TileKey &x, const TileKey &y) { return std::tie(x.tileCount, x.slot, x.matching, x.hash) < std::tie(y.tileCount, y.slot, y.matching, y.hash); };
auto byMatching = [](const TileKey &x, const TileKey &y) { return std::tie(x.tileCount, x.slot, x.matching) < std::tie(y.tileCount, y.slot, y.matching); };
for (size_t i = cBegin; i < c; i++) {
    const CallSide &curSide = curSides[i];
    if (!curSide.tileInterpolation) continue;
    for (uint32_t t = 0; t < curSide.tileCount; t++) {
        const uint32_t curTile = curSide.tileIndex + t;
        auto addRange = [&](std::pair<std::vector<TileKey>::iterator, std::vector<TileKey>::iterator> range) {
            for (auto it = range.first; it != range.second; it++) tileCheckSet.emplace_back(curTile, it->tileIndex);
        };

        if (curSide.tileMatching) {
            const uint64_t curHash = firstCurWorkload.drawData.callTiles[curTile].tmemHashOrID;
            addRange(std::equal_range(prevTiles.begin(), prevTiles.end(), TileKey{ curSide.tileCount, t, false, 0, 0 }, byMatching));
            addRange(std::equal_range(prevTiles.begin(), prevTiles.end(), TileKey{ curSide.tileCount, t, true, curHash, 0 }, byHash));
        }
        else {
            addRange(std::equal_range(prevTiles.begin(), prevTiles.end(), TileKey{ curSide.tileCount, t, false, 0, 0 }, bySlot));

// Look at: distinct indices on each side.
curLookAts.clear();
prevLookAts.clear();
for (size_t i = cBegin; i < c; i++) if (curSides[i].textureGen) curLookAts.emplace_back(curSides[i].lookAt);
for (size_t i = qBegin; i < q; i++) if (prevSides[i].textureGen) prevLookAts.emplace_back(prevSides[i].lookAt);
std::sort(curLookAts.begin(), curLookAts.end());
curLookAts.erase(std::unique(curLookAts.begin(), curLookAts.end()), curLookAts.end());
std::sort(prevLookAts.begin(), prevLookAts.end());
prevLookAts.erase(std::unique(prevLookAts.begin(), prevLookAts.end()), prevLookAts.end());
for (uint32_t curLookAt : curLookAts) {
    for (uint32_t prevLookAt : prevLookAts) {
        lookAtCheckSet.emplace_back(curLookAt, prevLookAt);

auto sortUnique = [](std::vector<IndexPair> &pairs) {
    std::sort(pairs.begin(), pairs.end());
    pairs.erase(std::unique(pairs.begin(), pairs.end()), pairs.end());
};

sortUnique(transformCheckSet);
sortUnique(tileCheckSet);
sortUnique(lookAtCheckSet);
